import { expect, expectStatus, test, type Document, type Extraction, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "approving the replacement approves a vendor whose other documents were already approved",
    { tag: "@LIF-06" },
    async ({ apiAs, factory }) => {
      // Arrange: a vendor in review; the reviewer approves two documents and rejects the w9
      const reviewer = await apiAs("reviewer");
      const member = await apiAs("member");
      const { vendor, extractions } = await factory.vendorInReview();
      for (const kind of ["insurance_certificate", "contract"] as const) {
        await expectStatus(
          await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
          200,
        );
      }
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
          data: { decision: "reject", note: "Wrong legal name" },
        }),
        200,
      );

      // Arrange: the member uploads a replacement w9, waits for extraction, and resubmits
      const replacement = await factory.upload(vendor.id, "w9");
      await expect
        .poll(
          async () =>
            (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
          { message: "replacement w9 is extracted", timeout: 30_000 },
        )
        .toBe("extracted");
      const resubmitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
      expect(resubmitted.status).toBe("in_review");
      const pending = await factory.extraction(replacement.id, "reviewer");
      expect(pending.status).toBe("pending_review");

      // Act: the reviewer approves the replacement's extraction
      await expectStatus<Extraction>(
        await reviewer.post(`/api/extractions/${pending.id}/decision`, { data: { decision: "approve" } }),
        200,
      );

      // Assert: the vendor is approved, the extraction is stored as approved, and the audit trail records it
      const stored = await expectStatus<Vendor>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
      expect(stored.status).toBe("approved");
      expect((await factory.extraction(replacement.id, "reviewer")).status).toBe("approved");
      const audit = await expectStatus<{ items: { action: string }[] }>(
        await reviewer.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
    },
  );
});
